layer.css:
@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700&family=Orbitron:wght@400;700&display=swap");
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-surface); font-style: normal; letter-spacing: 0.8px; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-radius: 6px; transition: all }
[data-ryt="brand"] { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: color-mix(in srgb, var(--ryt-accent) 65%, transparent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 65%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out; position: relative }
[data-ryt="button"] { color: var(--ryt-surface); background-color: rgb(13, 110, 253); border-top: 1px solid rgb(13, 110, 253); border-right: 1px solid rgb(13, 110, 253); border-bottom: 1px solid rgb(13, 110, 253); border-left: 1px solid rgb(13, 110, 253); border-radius: 6px 0px 0px 6px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-surface); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 6px; padding-right: 12px; padding-bottom: 6px; padding-left: 12px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(13, 110, 253); border-radius: 0px; font-weight: 600; font-style: normal; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(13, 110, 253); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: color-mix(in srgb, var(--ryt-text) 75%, transparent); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.5; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 75%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 6px }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 600; font-style: normal; line-height: 1.2; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"]:hover { color: #fff; background-color: #0d6efd; color: #0d6efd; background-color: transparent }
[data-ryt="nav"] a::before { content: ""; display: block; position: absolute; width: 59.4531px; height: 2px; color: color-mix(in srgb, var(--ryt-accent) 65%, transparent); background-color: rgb(0, 173, 181); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: 0.8px; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-accent) 65%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: transform 0.3s cubic-bezier(1, 0, 0, 1); -webkit-text-fill-color: color-mix(in srgb, var(--ryt-accent) 65%, transparent); bottom: 6px; left: 3.29688px }
[data-ryt="nav"] a:hover { color: color-mix(in srgb, var(--ryt-accent) 80%, transparent) }
[data-ryt="brand"]:hover { color: var(--ryt-accent) }
